.monitor-page {
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
  font-family: system-ui, -apple-system, sans-serif;
  background: #0b1021;
  min-height: 100vh;
  color: #e2e8f0;
}

header {
  text-align: center;
  margin-bottom: 28px;
}

header h1 { margin: 0 0 8px; font-size: 1.5rem; }

.overall {
  display: inline-block;
  padding: 6px 20px;
  border-radius: 999px;
  font-weight: 600;
}

.overall.ok   { background: #064e3b; color: #6ee7b7; }
.overall.warn { background: #422006; color: #fde047; }
.overall.fail { background: #450a0a; color: #fca5a5; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 28px;
}

.card {
  background: #111827;
  border-radius: 14px;
  padding: 18px;
  border: 2px solid transparent;
  transition: border-color .3s;
}

.card.ok   { border-color: #22c55e; }
.card.warn { border-color: #eab308; }
.card.fail { border-color: #ef4444; }

.card h2 {
  margin: 0 0 10px;
  font-size: 0.88rem;
  color: #94a3b8;
  font-weight: 500;
}

.big {
  font-size: 2.2rem;
  font-weight: 800;
  margin: 0 0 4px;
  color: #f8fafc;
}

.big small {
  font-size: 0.85rem;
  font-weight: 500;
  color: #94a3b8;
}

.sub {
  margin: 0;
  font-size: 0.78rem;
  color: #64748b;
}

.status {
  font-size: 1.1rem;
  font-weight: 700;
  margin: 0;
}

.bar {
  height: 10px;
  background: #1f2937;
  border-radius: 999px;
  overflow: hidden;
  margin: 8px 0 4px;
}

.fill {
  height: 100%;
  background: #22c55e;
  border-radius: 999px;
  transition: width .5s ease;
}

.fill.warn { background: #ef4444; }

.section {
  background: #111827;
  border-radius: 14px;
  padding: 18px;
  margin-bottom: 20px;
}

.section h2 {
  margin: 0 0 14px;
  font-size: 1rem;
  color: #94a3b8;
}

.chart {
  height: 140px;
  display: flex;
  align-items: flex-end;
}

.bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  width: 100%;
  height: 100%;
}

.bar {
  flex: 1;
  min-width: 3px;
  border-radius: 2px;
  transition: height .3s;
}

.log-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 360px;
  overflow-y: auto;
}

.log-item {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 0.82rem;
  background: #0b1021;
}

.log-item.error { border-left: 3px solid #ef4444; }
.log-item.warn  { border-left: 3px solid #eab308; }
.log-item.log   { border-left: 3px solid #38bdf8; }

.time   { color: #64748b; font-size: 0.7rem; min-width: 60px; }
.badge  { min-width: 22px; text-align: center; }
.text   { flex: 1; word-break: break-all; }

.empty  { color: #64748b; text-align: center; margin: 0; padding: 12px 0; }

